import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { interpolateArcRotateCamera } from "@babylonjs/lite";

export function spinAround(
  camera: ArcRotateCamera,
  scene: SceneContext,
  turns: number,
): Promise<void> {
  const startAlpha = camera.alpha;
  const goalAlpha = startAlpha + Math.PI * 2 * turns;

  return interpolateArcRotateCamera(
    camera,
    scene,
    {
      alpha: goalAlpha,
      beta: camera.beta,
      radius: camera.radius,
      target: camera.target,
    },
  );
}
```

I added `src/turntable.ts` and implemented `spinAround` by delegating to the library’s `interpolateArcRotateCamera`, targeting `alpha + 2π·turns` while keeping beta, radius, and target unchanged. I wasn’t fully certain whether the library’s interpolation treats `alpha` as an unwrapped numeric value or normalizes it internally, but I used the exposed smooth transition API as requested.
